\title{Lower Bounds on Clique Densities via Codegrees\\ and the Inclusion--Exclusion Inverse}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
We isolate a single elementary inequality --- the \emph{inclusion--exclusion inverse}
$\deg(u) + \deg(v) \le n + \codeg(u,v)$ relating the degrees of two vertices, the
order $n$ of the graph, and the number of their common neighbors --- and show that it
simultaneously governs three classical phenomena in extremal graph theory: the
existence of triangles, the structure of extremal triangle-free graphs, and the
global count of triangles. From the inverse we derive, in one stroke: (i) a codegree
threshold guaranteeing a common neighbor, hence a \emph{forced triangle} whenever an
edge is over-heavy ($\deg(u)+\deg(v) > n$); (ii) Mantel's local degree condition, the
contrapositive statement that every edge of a triangle-free graph is degree-light;
(iii) an exact identity expressing six times the triangle count as a sum of codegrees
over ordered adjacent pairs; and (iv) a Goodman-type global lower bound on the
triangle count in terms of the degree sequence. We emphasize that the additive
formulation $\deg(u)+\deg(v) \le n + \codeg(u,v)$ is strictly more robust than the
subtractive $\codeg(u,v) \ge \deg(u)+\deg(v)-n$, which becomes vacuous once its
right-hand side truncates to zero. The unifying viewpoint recovers, from one line of
counting, results usually attributed to Mantel (1907), Tur\'an (1941), and Goodman
(1959), and situates them as the $r=3$ base case of the
Bollob\'as--Khadziivanov--Nikiforov complete-subgraph recursion.
\end{abstract}

\section{Introduction}

Extremal graph theory asks how a global constraint on a graph forces or forbids local
structure. Among its foundational results are three concerning the humblest
nontrivial clique, the triangle: Mantel's theorem (1907), that a triangle-free graph
on $n$ vertices has at most $\lfloor n^2/4\rfloor$ edges; Tur\'an's theorem (1941) and
Zykov's refinement (1949) for $K_r$-free graphs; and Goodman's bound (1959), a lower
bound on the number of triangles in terms of the number of edges. These are usually
proved by separate arguments. We show that all three --- in their $r=3$ form ---
descend from one elementary inequality, the inclusion--exclusion inverse, and that the
passage between them amounts to reading that inequality forward (existence), by
contraposition (extremal structure), or after summation (global counting).

Throughout, $G$ is a finite simple graph on a vertex set $V$ with $|V| = n$. For a
vertex $u$ we write $N(u)$ for its neighborhood and $\deg(u) = |N(u)|$ for its degree.

\section{Definitions}

\begin{definition}[Codegree]
For vertices $u, v \in V$, the \emph{codegree} of the ordered pair $(u,v)$ is
\[ \codeg(u,v) = |N(u) \cap N(v)|, \]
the number of common neighbors of $u$ and $v$.
\end{definition}

The codegree is symmetric, $\codeg(u,v) = \codeg(v,u)$. A vertex
$w \in N(u) \cap N(v)$ is exactly a common neighbor of $u$ and $v$; if in addition
$uv$ is an edge, then $\{u,v,w\}$ is a triangle. Thus for an edge $uv$, $\codeg(u,v)$
counts the triangles through that edge.

\begin{definition}[Over-heavy and degree-light edges]
An edge $uv$ is \emph{over-heavy} if $\deg(u) + \deg(v) > n$ and \emph{degree-light} if
$\deg(u) + \deg(v) \le n$.
\end{definition}

\begin{definition}[Triangle count]
We write $t(G)$ for the number of unordered triangles ($3$-cliques) in $G$.
\end{definition}

\section{The inclusion--exclusion inverse}

\begin{theorem}[Inclusion--Exclusion Inverse]\label{thm:inverse}
For all $u, v \in V$,
\[ \deg(u) + \deg(v) \ \le\ n + \codeg(u,v). \]
\end{theorem}

\begin{proof}
The inclusion--exclusion identity for two finite sets gives
\[ |N(u) \cup N(v)| + |N(u) \cap N(v)| = |N(u)| + |N(v)| = \deg(u) + \deg(v). \]
Since $N(u) \cup N(v) \subseteq V$, we have $|N(u) \cup N(v)| \le n$. Substituting,
\[ \deg(u) + \deg(v) = |N(u) \cup N(v)| + \codeg(u,v) \le n + \codeg(u,v). \qedhere \]
\end{proof}

\begin{remark}[Additive vs.\ subtractive form]
Rearranged over the integers, Theorem~\ref{thm:inverse} reads
$\codeg(u,v) \ge \deg(u) + \deg(v) - n$. When $\deg(u)+\deg(v) \le n$ the right-hand
side is nonpositive and this bound is vacuous. The additive form carries information
at every degree profile, is used in all subsequent results, and sidesteps truncated
subtraction over the natural numbers.
\end{remark}

\section{Existence: forced triangles}

\begin{theorem}[Codegree threshold $\Rightarrow$ common neighbor]\label{thm:common}
If $\deg(u) + \deg(v) > n$, then $u$ and $v$ have a common neighbor.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:inverse}, $\codeg(u,v) \ge \deg(u)+\deg(v)-n > 0$, so
$N(u) \cap N(v)$ is nonempty. Any element is a common neighbor.
\end{proof}

\begin{theorem}[Forced Triangle]\label{thm:forced}
If $uv$ is an edge with $\deg(u)+\deg(v) > n$, then $G$ contains a triangle; in
particular $G$ is not triangle-free.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:common} there is a vertex $w$ adjacent to both $u$ and $v$. Since
$uv$ is an edge, $\{u,v,w\}$ is pairwise adjacent, hence a triangle.
\end{proof}

\begin{remark}[Non-vacuity]
The hypothesis $\deg(u)+\deg(v)>n$ is satisfiable in any sufficiently dense graph, and
Theorem~\ref{thm:forced} then produces a genuine triangle. This is the $r=3$ base case
of the Bollob\'as--Khadziivanov--Nikiforov recursion, in which the same overlap
argument applied inside a common neighborhood forces successively larger complete
subgraphs.
\end{remark}

\section{Extremal structure: Mantel's local condition}

\begin{theorem}[Mantel's Local Degree Condition]\label{thm:mantel}
If $G$ is triangle-free, then every edge $uv$ is degree-light:
$\deg(u) + \deg(v) \le n$.
\end{theorem}

\begin{proof}
This is the contrapositive of Theorem~\ref{thm:forced}: an over-heavy edge would force
a triangle, contradicting triangle-freeness.
\end{proof}

\begin{corollary}[Mantel's theorem]
A triangle-free graph on $n$ vertices has at most $\lfloor n^2/4\rfloor$ edges.
\end{corollary}

\begin{proof}[Proof sketch]
Summing Theorem~\ref{thm:mantel} over all edges gives
$\sum_{uv \in E}(\deg(u)+\deg(v)) \le n|E|$. The left side equals
$\sum_w \deg(w)^2 \ge (2|E|)^2/n$ by Cauchy--Schwarz, so $(2|E|)^2/n \le n|E|$, i.e.
$|E| \le n^2/4$. Equality forces the balanced complete bipartite graph.
\end{proof}

\section{Global counting: codegree identity and Goodman's bound}

\begin{theorem}[Ordered-Triangle Codegree Identity]\label{thm:identity}
\[ \sum_{u \in V}\ \sum_{v \in N(u)} \codeg(u,v) \ =\ 6\, t(G). \]
\end{theorem}

\begin{proof}
Writing $\codeg(u,v) = \sum_{w \in N(u)\cap N(v)} 1$, the triple sum counts ordered
triples $(u,v,w)$ with $v \in N(u)$, $w \in N(u)$, $w \in N(v)$ --- i.e.\ ordered
triples of pairwise-adjacent vertices. Each unordered triangle contributes exactly
$3! = 6$ such orderings.
\end{proof}

\begin{theorem}[Goodman-type Codegree Lower Bound]\label{thm:goodman}
\[ \sum_{u \in V}\ \sum_{v \in N(u)} \bigl(\deg(u) + \deg(v)\bigr) \ \le\
   \Bigl(\sum_{u \in V}\ \sum_{v \in N(u)} n\Bigr) + 6\, t(G). \]
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:inverse} termwise over all ordered adjacent pairs and use
Theorem~\ref{thm:identity} to replace the codegree sum by $6\,t(G)$.
\end{proof}

\begin{remark}[Recovering Goodman's classical form]
Here $\sum_u\sum_{v\in N(u)} n = 2n|E|$ and $\sum_u\sum_{v\in N(u)}(\deg u+\deg v) =
2\sum_w \deg(w)^2$, so Theorem~\ref{thm:goodman} reads
$2\sum_w \deg(w)^2 \le 2n|E| + 6t(G)$, whence
\[ t(G) \ \ge\ \tfrac{1}{3}\Bigl(\textstyle\sum_w \deg(w)^2 - n|E|\Bigr)
      \ \ge\ \frac{|E|(4|E|-n^2)}{3n}, \]
positive exactly when $|E| > n^2/4$, the Mantel threshold.
\end{remark}

\section{Algorithms}

\textbf{Codegree matrix.} Intersect adjacency bitsets to compute all $\codeg(u,v)$ in
$O(n^3/w)$ word operations. \textbf{Over-heavy edge scan.} For each edge with
$\deg(u)+\deg(v) > n$, scan $N(u)\cap N(v)$ for a witness $w$, certifying a triangle.
\textbf{Goodman evaluator.} From the degree sequence, compute
$\tfrac13(\sum_w\deg(w)^2 - n|E|)$ and compare with the exact count from
Theorem~\ref{thm:identity}.

\section{Applications and discussion}

Any pair of hubs whose combined degree exceeds $n$ is guaranteed a common contact ---
an unavoidable triadic closure; the Goodman bound quantifies this at scale, so high
connectivity mechanically produces clustering. The organizing principle is that a
single inequality, obtained by inverting inclusion--exclusion against
$|N(u)\cup N(v)| \le n$, controls existence, extremal structure, and counting. Its
slack lives entirely in the average gap $n - |N(u)\cup N(v)|$, which vanishes for
quasi-random neighborhoods.

\section{Future work}

Four directions extend the viewpoint: a \emph{codegree tensor inverse} for $K_r$ with
signs given by the M\"obius function of the neighborhood intersection lattice;
\emph{stability} of graphs on the equality locus $\deg(u)+\deg(v)=n$ toward complete
bipartite graphs; \emph{tightness} of the Goodman bound along near-regular
quasi-random families, with deficit proportional to degree-sequence variance; and
\emph{threshold cascades} forcing a $K_r$ whose order grows with the degree-sum
overshoot.

