"""
Empirical study of the slack in the inclusion-exclusion inverse across
random graphs, illustrating that the deficit n - |N(u) ∪ N(v)| controls
the gap in the Goodman bound.
"""
from __future__ import annotations
import random
from itertools import combinations
from typing import Dict, Set, List, Tuple

Graph = Dict[int, Set[int]]


def random_graph(n: int, p: float, seed: int) -> Graph:
    rng = random.Random(seed)
    g: Graph = {v: set() for v in range(n)}
    for u, v in combinations(range(n), 2):
        if rng.random() < p:
            g[u].add(v)
            g[v].add(u)
    return g


def degree(g: Graph, u: int) -> int:
    return len(g[u])


def edges(g: Graph) -> List[Tuple[int, int]]:
    return [(u, v) for u in g for v in g[u] if u < v]


def num_triangles(g: Graph) -> int:
    return sum(1 for a, b, c in combinations(sorted(g), 3)
               if b in g[a] and c in g[a] and c in g[b])


def mean_union_deficit(g: Graph) -> float:
    """Average of n - |N(u) ∪ N(v)| over adjacent ordered pairs."""
    n = len(g)
    total, count = 0, 0
    for u in g:
        for v in g[u]:
            union = len(g[u] | g[v])
            total += n - union
            count += 1
    return total / count if count else 0.0


def goodman_edge_bound(g: Graph) -> float:
    n, m = len(g), len(edges(g))
    return m * (4 * m - n * n) / (3.0 * n)


def main() -> None:
    n = 40
    print(f"Random graphs on n={n} vertices; comparing Goodman bound to truth")
    print(f"{'p':>5} {'edges':>7} {'t(G)':>7} {'bound':>10} {'gap':>10} {'deficit':>9}")
    for p in [0.2, 0.35, 0.5, 0.65, 0.8]:
        g = random_graph(n, p, seed=1)
        t = num_triangles(g)
        b = goodman_edge_bound(g)
        print(f"{p:>5.2f} {len(edges(g)):>7d} {t:>7d} {b:>10.1f} "
              f"{t-b:>10.1f} {mean_union_deficit(g):>9.3f}")


if __name__ == "__main__":
    main()

"""
Certifying non-triangle-freeness cheaply: the over-heavy edge scan finds a
triangle without enumerating all triples, and we compare its cost to the
brute-force triple enumeration on the same graphs.
"""
from __future__ import annotations
import random
from itertools import combinations
from typing import Dict, Set, Optional, Tuple, List

Graph = Dict[int, Set[int]]


def random_graph(n: int, p: float, seed: int) -> Graph:
    rng = random.Random(seed)
    g: Graph = {v: set() for v in range(n)}
    for u, v in combinations(range(n), 2):
        if rng.random() < p:
            g[u].add(v)
            g[v].add(u)
    return g


def overheavy_certificate(g: Graph) -> Tuple[Optional[Tuple[int, int, int]], int]:
    """
    Scan edges; on the first edge with deg u + deg v > n, return a triangle
    witness from the (provably nonempty) common neighborhood. Also return the
    number of edges inspected.
    """
    n = len(g)
    inspected = 0
    for u in g:
        for v in g[u]:
            if u < v:
                inspected += 1
                if len(g[u]) + len(g[v]) > n:
                    common = g[u] & g[v]  # nonempty by the overlap rule
                    if common:
                        return (u, v, min(common)), inspected
    return None, inspected


def brute_force_triangle(g: Graph) -> Tuple[Optional[Tuple[int, int, int]], int]:
    inspected = 0
    for a, b, c in combinations(sorted(g), 3):
        inspected += 1
        if b in g[a] and c in g[a] and c in g[b]:
            return (a, b, c), inspected
    return None, inspected


def main() -> None:
    n = 60
    for p in [0.4, 0.55, 0.7]:
        g = random_graph(n, p, seed=7)
        cert, ins_c = overheavy_certificate(g)
        bf, ins_b = brute_force_triangle(g)
        print(f"p={p}: certificate {cert} after {ins_c} edge checks; "
              f"brute force found {bf} after {ins_b} triple checks")


if __name__ == "__main__":
    main()

