function CODEGREE_MATRIX(G on vertices V, |V| = n):
    for each u in V:
        N[u] <- neighbor set of u
    allocate C[n][n]
    for each u in V:
        for each v in V:
            C[u][v] <- |N[u] intersect N[v]|
    return C

function FORCED_TRIANGLE(G on vertices V, |V| = n):
    for each edge (u, v) in E(G):
        if deg(u) + deg(v) > n:
            common <- N(u) intersect N(v)   # nonempty by the inverse
            w <- any element of common
            return (u, v, w)
    return NONE   # every edge degree-light: Mantel condition holds

