Graph = Dict[int, Set[int]]


def forced_triangle(g: Graph) -> Optional[Tuple[int, int, int]]:
    """Return an explicit triangle forced by an over-heavy edge, or None."""
    n: int = len(g)
    for u in g:
        for v in g[u]:
            if u < v and len(g[u]) + len(g[v]) > n:
                common: Set[int] = g[u] & g[v]  # guaranteed nonempty
                if common:
                    return (u, v, min(common))
    return None

