function GOODMAN_BOUNDS(G on vertices V, |V| = n):
    m <- |E(G)|
    S2 <- sum over w in V of deg(w)^2
    degree_bound <- (S2 - n * m) / 3
    edge_bound   <- m * (4*m - n*n) / (3*n)
    return (degree_bound, edge_bound)
